using SenicPosSaaS.Domain.Common;
using SenicPosSaaS.Domain.Enums;

namespace SenicPosSaaS.Domain.Entities;

public class Order : TenantEntity
{
    public string OrderNumber { get; set; } = string.Empty;
    /// <summary>Null for a walk-in customer.</summary>
    public Guid? CustomerId { get; set; }
    /// <summary>
    /// Id generated by the client for this sale. A repeated request with the same id returns the
    /// existing order instead of creating a second one (retries, offline sync).
    /// </summary>
    public Guid? ClientOrderId { get; set; }
    public Customer? Customer { get; set; }
    public decimal TotalAmount { get; set; }
    public decimal DiscountAmount { get; set; }
    public decimal TaxAmount { get; set; }
    public decimal NetAmount { get; set; }
    /// <summary>How the shop's prices related to VAT when the bill was made; a reprint never changes.</summary>
    public VatMode VatMode { get; set; }
    /// <summary>The VAT rate used, e.g. 7. Meaningless when <see cref="VatMode"/> is None.</summary>
    public decimal VatRatePercent { get; set; }
    /// <summary>Points this bill gave its customer; taken back if the bill is cancelled.</summary>
    public int PointsEarned { get; set; }
    public OrderStatus Status { get; set; }
    public PaymentMethod PaymentMethod { get; set; }
    public DateTime? CompletedAt { get; set; }
    public string? Notes { get; set; }
    
    public ICollection<OrderItem> OrderItems { get; set; } = new List<OrderItem>();
}
